sikkerhet.js:
// Faktisk Studio · Bevissikring — arkivmappe, sikkerhet og oppfølging
// (lastes etter main.js og bruker state, els, setStatus, refresh, render)
//
//  • Arkivmappa må velges før noe sikres — ingen stille standardmappe.
//    Varsler hvis mappa synkes til iCloud, Google Drive, Dropbox eller OneDrive.
//  • Kryptert arkiv: et macOS-diskbilde (AES-256) som låses opp med passord.
//  • Innstillinger: navn i manifestet, uavhengig tidsstempel, tempo på SoMe.
//  • Tempo: tilfeldige pauser mellom innlegg og nedslag (window.bvPace).
//  • Stories fra Instagram, og «Følg med» på sikrede adresser.

(function () {
  const api = window.faktisk;
  const $ = id => document.getElementById(id);
  if (typeof api.bevisSettingsGet !== 'function') return;
  const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

  const el = {
    setup: $('rootSetup'), setupPick: $('setupPickBtn'), setupVault: $('setupVaultBtn'),
    warn: $('rootWarn'), vaultBox: $('vaultBox'), vaultInfo: $('vaultInfo'), vaultPw: $('vaultPw'), vaultOpen: $('vaultOpenBtn'), vaultClose: $('vaultCloseBtn'),
    vForm: $('vaultForm'), vName: $('vName'), vSize: $('vSize'), vPw: $('vPw'), vPw2: $('vPw2'), vCreate: $('vCreateBtn'), vCancel: $('vCancelBtn'),
    name: $('setName'), account: $('setAccount'), stamp: $('setStamp'), pace: $('setPace'), newVault: $('newVaultBtn'),
    stories: $('storiesBtn'),
  };
  state.settings = { timestamp: true, userName: '', pace: 'forsiktig' };
  state.vault = null;
  state.watches = [];
  state.rootInfo = null;

  // ------------------------------------------------------------
  //  Arkivmappe
  // ------------------------------------------------------------
  async function rootChanged() {
    const has = !!state.root;
    el.setup.hidden = has;
    document.body.classList.toggle('bv-noroot', !has);
    state.rootInfo = has ? await api.bevisPathInfo({ path: state.root }) : null;
    const s = await api.bevisSettingsGet();
    state.vault = s.vault;
    const info = state.rootInfo || {};
    const warn = [];
    if (has && info.cloud) warn.push('Mappa synkes til ' + esc(info.cloud) + '. Sikringene havner da også i skyen — hos en tredjepart, og kanskje på andre maskiner. Velg en lokal mappe eller et kryptert arkiv for kildesensitivt materiale.');
    if (has && !info.exists) warn.push(info.vault || (state.vault && state.root.startsWith('/Volumes/')) ? 'Det krypterte arkivet er låst. Lås det opp nedenfor.' : 'Mappa finnes ikke lenger (flyttet, eller på en disk som ikke er koblet til). Velg mappe på nytt.');
    el.warn.innerHTML = warn.map(w => '<p class="bv-hint bv-hint--warn">' + w + '</p>').join('');
    // Kryptert arkiv
    const v = state.vault;
    el.vaultBox.hidden = !v;
    if (v) {
      el.vaultInfo.innerHTML = 'Kryptert arkiv «' + esc(v.name) + '» — ' + (v.mounted ? '<b>åpent</b>' : 'låst');
      el.vaultPw.hidden = el.vaultOpen.hidden = !!v.mounted;
      el.vaultClose.hidden = !v.mounted;
    }
    const blocked = !has || !info.exists;
    ['captureBtn', 'regionBtn', 'videoBtn', 'storiesBtn', 'planBtn', 'runBtn', 'pInfoBtn', 'pScanBtn', 'pRunBtn', 'linkExtBtn'].forEach(id => {
      const b = $(id); if (b) b.classList.toggle('bv-needroot', blocked);
    });
  }
  window.bvRootChanged = rootChanged;
  window.bvRootReady = function () {
    if (!state.root) { setStatus('Velg arkivmappe først — se øverst til venstre', 'err'); el.setup.hidden = false; el.setup.scrollIntoView({ block: 'nearest' }); return false; }
    if (state.rootInfo && !state.rootInfo.exists) { setStatus(state.rootInfo.vault ? 'Lås opp det krypterte arkivet først' : 'Arkivmappa finnes ikke — velg den på nytt', 'err'); return false; }
    return true;
  };

  async function pick() {
    const r = await api.openFileDialog({ title: 'Velg mappe for bevissikring', properties: ['openDirectory', 'createDirectory'] });
    if (r.canceled) return;
    const info = await api.bevisPathInfo({ path: r.path });
    if (info.cloud) {
      const ok = await window.faktiskDialog.confirm('Mappa synkes til ' + info.cloud + '. Alt som sikres, lastes da også opp dit. Bruke den likevel?', true);
      if (!ok) return;
    }
    setRoot(r.path);
  }
  function setRoot(p) {
    state.root = p;
    if (typeof renderRoot === 'function') renderRoot();
    scheduleSaveState(); refresh(); rootChanged();
  }
  el.setupPick.addEventListener('click', pick);
  window.bvPickRoot = pick;

  // ------------------------------------------------------------
  //  Kryptert arkiv
  // ------------------------------------------------------------
  function showVaultForm(show) {
    el.vForm.hidden = !show;
    if (show) { el.vPw.value = el.vPw2.value = ''; el.vName.focus(); el.vForm.scrollIntoView({ block: 'nearest' }); }
  }
  el.setupVault.addEventListener('click', () => showVaultForm(true));
  el.newVault.addEventListener('click', () => showVaultForm(true));
  el.vCancel.addEventListener('click', () => showVaultForm(false));
  el.vCreate.addEventListener('click', async () => {
    if (el.vPw.value.length < 8) { setStatus('Passordet må ha minst 8 tegn', 'err'); el.vPw.focus(); return; }
    if (el.vPw.value !== el.vPw2.value) { setStatus('Passordene er ikke like', 'err'); el.vPw2.focus(); return; }
    const where = await api.openFileDialog({ title: 'Hvor skal arkivfila ligge?', properties: ['openDirectory', 'createDirectory'] });
    if (where.canceled) return;
    const info = await api.bevisPathInfo({ path: where.path });
    if (info.cloud && !(await window.faktiskDialog.confirm('Arkivfila havner i ' + info.cloud + '. Innholdet er kryptert, men fila synkes. Fortsette?', true))) return;
    el.vCreate.disabled = true;
    setStatus('Lager kryptert arkiv …');
    try {
      const r = await api.bevisVaultCreate({ dir: where.path, name: el.vName.value.trim(), sizeGB: +el.vSize.value || 50, password: el.vPw.value });
      if (!r.ok) { setStatus('Fikk ikke laget arkivet: ' + r.error, 'err'); return; }
      showVaultForm(false);
      setStatus('Kryptert arkiv laget og åpnet. Passordet lagres ikke — ta vare på det (f.eks. i redaksjonens passordhvelv).', 'ok');
      setRoot(r.mountpoint);
    } finally { el.vCreate.disabled = false; el.vPw.value = el.vPw2.value = ''; }
  });
  el.vaultOpen.addEventListener('click', async () => {
    const r = await api.bevisVaultOpen({ password: el.vaultPw.value });
    el.vaultPw.value = '';
    if (!r.ok) { setStatus(r.error, 'err'); return; }
    setStatus('Arkivet er åpent', 'ok');
    if (!state.root || state.root.startsWith('/Volumes/')) setRoot(r.mountpoint); else rootChanged();
  });
  el.vaultPw.addEventListener('keydown', e => { if (e.key === 'Enter') el.vaultOpen.click(); });
  el.vaultClose.addEventListener('click', async () => {
    const r = await api.bevisVaultClose();
    if (!r.ok) { setStatus('Fikk ikke låst: ' + r.error, 'err'); return; }
    setStatus('Arkivet er låst', 'ok');
    rootChanged(); refresh();
  });

  // ------------------------------------------------------------
  //  Innstillinger
  // ------------------------------------------------------------
  let setTimer = null;
  function saveSettings() {
    clearTimeout(setTimer);
    setTimer = setTimeout(() => {
      state.settings = { userName: el.name.value.trim(), account: el.account ? el.account.value.trim() : '', timestamp: el.stamp.checked, pace: el.pace.value };
      api.bevisSettingsSet(state.settings).catch(() => {});
    }, 300);
  }
  el.name.addEventListener('input', saveSettings);
  if (el.account) el.account.addEventListener('input', saveSettings);
  el.stamp.addEventListener('change', saveSettings);
  el.pace.addEventListener('change', saveSettings);

  // Tilfeldig pause mellom elementer i en serie. Faste intervaller og høyt
  // tempo er det plattformene ser etter når de stenger kontoer.
  window.bvPace = async function (isStopped) {
    const careful = state.settings.pace !== 'normal';
    const ms = careful ? 8000 + Math.random() * 17000 : 2500 + Math.random() * 5000;
    const until = Date.now() + ms;
    while (Date.now() < until) {
      if (isStopped && isStopped()) return;
      setStatus('Pause ' + Math.ceil((until - Date.now()) / 1000) + ' s (' + (careful ? 'forsiktig' : 'normalt') + ' tempo) …');
      await new Promise(r => setTimeout(r, 500));
    }
    setStatus('');
  };

  // ------------------------------------------------------------
  //  Stories
  // ------------------------------------------------------------
  el.stories.addEventListener('click', async () => {
    if (state.busy || !window.bvRootReady()) return;
    const caseName = els.caseInput.value.trim();
    if (!caseName) { setStatus('Skriv inn en sak — sikringene samles per sak', 'err'); els.caseInput.focus(); return; }
    const url = els.urlInput.value.trim();
    if (!url) { setStatus('Lim inn lenken til Instagram-profilen', 'err'); els.urlInput.focus(); return; }
    setBusy(true);
    setStatus('Henter stories …');
    try {
      const r = await api.bevisStories({ root: state.root, caseName, url, note: els.noteInput.value.trim(), pluginVersion: state.pluginVersion });
      if (r.cancelled) { setStatus('Avbrutt'); return; }
      if (!r.ok) { setStatus(r.error, 'err'); return; }
      state.highlight = r.dir;
      setStatus('Stories lagret (' + fmtSize(r.bytes) + ')', 'ok');
      await refresh();
    } finally { setBusy(false); }
  });

  // ------------------------------------------------------------
  //  Følg med
  // ------------------------------------------------------------
  window.bvWatchFor = dir => state.watches.find(w => w.dir === dir) || null;
  window.bvCardAction = async function (act, it, btn) {
    if (act === 'stamp') {
      btn.disabled = true; btn.textContent = 'Henter …';
      const r = await api.bevisStamp({ dir: it.dir });
      if (!r.ok) setStatus('Tidsstempel feilet: ' + r.error, 'err'); else setStatus('Tidsstemplet ' + fmtTime(r.genTime), 'ok');
      await refresh();
      return true;
    }
    if (act === 'watch') {
      const r = await api.bevisWatchAdd({ dir: it.dir, hours: 24 });
      setStatus(r.ok ? 'Følger med på adressen — sjekkes hver 24. time mens Studio er åpent' : r.error, r.ok ? 'ok' : 'err');
      return true;
    }
    if (act === 'unwatch') {
      const w = window.bvWatchFor(it.dir);
      if (w) await api.bevisWatchRemove({ id: w.id });
      return true;
    }
    if (act === 'watchnow') {
      const w = window.bvWatchFor(it.dir);
      if (w) { await api.bevisWatchCheck({ id: w.id }); setStatus('Sjekker adressen …'); }
      return true;
    }
    return false;
  };
  window.bvWatchHtml = function (it) {
    const w = window.bvWatchFor(it.dir);
    if (!w) return '';
    const cls = w.lastStatus === 'borte' ? 'bad' : w.lastStatus === 'endret' ? 'warn' : 'ok';
    return '<div class="bv-watch bv-watch--' + cls + '">Følger med' + (w.lastCheck ? ' · sjekket ' + esc(fmtTime(w.lastCheck)) + ': ' + esc(w.lastStatus) + (w.lastDetail ? ' — ' + esc(w.lastDetail) : '') : ' · venter på første sjekk') +
      ' <button class="link-btn bv-inline" data-act="watchnow" type="button">Sjekk nå</button></div>';
  };
  async function loadWatches() {
    const r = await api.bevisWatchList();
    state.watches = (r && r.watches) || [];
    render();
  }
  if (api.onBevisWatchChanged) api.onBevisWatchChanged(list => { state.watches = list || []; render(); });

  // ------------------------------------------------------------
  //  Oppstart (main.js venter på denne før lista tegnes)
  // ------------------------------------------------------------
  window.bvSecurityInit = async function () {
    const s = await api.bevisSettingsGet();
    state.settings = s.settings;
    el.name.value = s.settings.userName || '';
    if (el.account) el.account.value = s.settings.account || '';
    el.stamp.checked = s.settings.timestamp !== false;
    el.pace.value = s.settings.pace || 'forsiktig';
    await loadWatches();
    await rootChanged();
  };
})();

stikkprove.js:
// Faktisk Studio · Bevissikring — stikkprøver (lastes etter main.js)
//
// Planen lages og lagres FØR innsamlingen (src/bevis-sample.js), så utvalget
// kan dokumenteres som systematisk. Kjøringen åpner hvert nedslag i
// sikringsvinduet og sikrer det med bevisCapture, merket med sample-info.
// Resultatet av hvert nedslag logges i resultat.json ved siden av planen,
// så en avbrutt plan kan fortsettes senere.

(function () {
  const $ = id => document.getElementById(id);
  const api = window.faktisk;
  if (typeof api.bevisPlanCreate !== 'function') return;

  const S = {
    mode: 'single',
    plans: [],          // fra bevisPlanList
    current: null,      // { dir, plan, results, fingerprint }
    running: false,
    stop: false,
  };
  const el = {
    modeSeg: $('modeSeg'), planSelect: $('planSelect'), form: $('planForm'),
    platform: $('sPlatform'), account: $('sAccount'), from: $('sFrom'), to: $('sTo'),
    firstBtn: $('sFirstBtn'), firstInfo: $('sFirstInfo'), mode: $('sMode'), n: $('sN'), nUnit: $('sNUnit'),
    win: $('sWindow'), per: $('sPer'), summary: $('sSummary'),
    planBtn: $('planBtn'), runBtn: $('runBtn'), stopBtn: $('stopBtn'),
    planBox: $('planBox'), planMeta: $('planMeta'), planList: $('planList'), planReveal: $('planRevealBtn'),
  };

  const DAY = 86400000;
  const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const pd = s => { const m = String(s || '').match(/^(\d{4})-(\d{2})-(\d{2})$/); return m ? Date.UTC(+m[1], +m[2] - 1, +m[3]) : NaN; };
  const fmtD = s => { const t = pd(s); return isNaN(t) ? s : new Date(t).toLocaleDateString('nb-NO', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' }); };
  const PLAT = { x: 'X', youtube: 'YouTube', facebook: 'Facebook', instagram: 'Instagram', tiktok: 'TikTok' };

  // ------------------------------------------------------------
  //  Modus
  // ------------------------------------------------------------
  function setMode(m) {
    S.mode = m === 'sample' || m === 'profile' ? m : 'single';
    document.body.classList.toggle('bv-mode-sample', S.mode === 'sample');
    document.body.classList.toggle('bv-mode-profile', S.mode === 'profile');
    el.modeSeg.querySelectorAll('button').forEach(b => b.classList.toggle('is-on', b.dataset.mode === S.mode));
    if (S.mode === 'sample') loadPlans();
    if (S.mode === 'profile' && window.bvProfileShown) window.bvProfileShown();
  }
  el.modeSeg.addEventListener('click', e => {
    const b = e.target.closest('button[data-mode]');
    if (!b || S.running || (window.bvProfileRunning && window.bvProfileRunning())) return;
    setMode(b.dataset.mode); scheduleSaveState();
  });

  // ------------------------------------------------------------
  //  Skjema
  // ------------------------------------------------------------
  function countWindows() {
    const a = pd(el.from.value), b = pd(el.to.value);
    if (isNaN(a) || isNaN(b) || b < a) return 0;
    const span = Math.round((b - a) / DAY) + 1;
    const n = Math.max(1, +el.n.value || 1);
    return el.mode.value === 'count' ? Math.min(n, span) : Math.ceil(span / n);
  }
  function updateForm() {
    const p = el.platform.value;
    document.body.classList.toggle('bv-plat-youtube', p === 'youtube');
    el.nUnit.textContent = el.mode.value === 'count' ? 'nedslag' : (+el.n.value === 1 ? 'dag' : 'dag');
    el.firstBtn.hidden = p !== 'youtube';
    if (p === 'x' && !el.firstInfo.dataset.keep) el.firstInfo.textContent = 'På X står startdatoen som «Ble med» på profilen.';
    if (p === 'youtube' && !el.firstInfo.dataset.keep) el.firstInfo.textContent = '';
    const c = countWindows();
    const w = Math.max(1, +el.win.value || 1);
    el.summary.textContent = c
      ? c + ' nedslag à ' + w + ' døgn' + (p === 'youtube' ? ', inntil ' + Math.max(1, +el.per.value || 1) + ' video(er) hver' : '') + (c > 60 ? ' — det tar tid' : '')
      : 'Velg en periode.';
  }
  [el.platform, el.mode, el.n, el.win, el.per, el.from, el.to, el.account].forEach(x => x.addEventListener('input', () => { updateForm(); scheduleSaveState(); }));
  [el.platform, el.mode].forEach(x => x.addEventListener('change', () => { updateForm(); scheduleSaveState(); }));

  // Lim inn en lenke → velg plattform automatisk
  el.account.addEventListener('change', async () => {
    const r = await api.bevisParseAccount({ account: el.account.value, platform: el.platform.value });
    if (r && r.platform && el.platform.querySelector('option[value="' + r.platform + '"]')) {
      el.platform.value = r.platform; updateForm();
    }
  });

  el.firstBtn.addEventListener('click', async () => {
    if (S.running) return;
    el.firstInfo.dataset.keep = '1';
    el.firstInfo.textContent = 'Henter videolisten …';
    setBusy(true);
    try {
      const r = await api.bevisYoutubeList({ account: el.account.value });
      if (!r.ok) { el.firstInfo.textContent = r.error; return; }
      if (!r.oldest) { el.firstInfo.textContent = r.count + ' videoer, men ingen datoer.'; return; }
      el.firstInfo.textContent = 'Sjekker nøyaktig dato …';
      const d = await api.bevisYoutubeDate({ id: r.oldest.id });
      const date = d.ok ? d.date : r.oldest.date;
      el.from.value = date;
      if (!el.to.value) el.to.value = new Date().toISOString().slice(0, 10);
      el.firstInfo.textContent = 'Første video: ' + fmtD(date) + (d.ok ? '' : ' (omtrentlig)') + ' · ' + r.count + ' videoer totalt';
      updateForm(); scheduleSaveState();
    } finally { setBusy(false); }
  });

  // ------------------------------------------------------------
  //  Planer
  // ------------------------------------------------------------
  async function loadPlans(selectDir) {
    if (!state.root) return;
    const r = await api.bevisPlanList({ root: state.root });
    S.plans = r.plans || [];
    const cur = selectDir || (S.current && S.current.dir) || '';
    el.planSelect.innerHTML = '<option value="">Ny plan …</option>' + S.plans.map(p =>
      '<option value="' + esc(p.dir) + '"' + (p.dir === cur ? ' selected' : '') + '>' +
      esc(p.case + ' · ' + (PLAT[p.plan.platform] || p.plan.platform) + ' ' + p.plan.account.handle + ' · ' + p.plan.period.from + '–' + p.plan.period.to) + '</option>').join('');
    if (cur) {
      const p = S.plans.find(x => x.dir === cur);
      if (p) S.current = { dir: p.dir, plan: p.plan, results: p.results };
    }
    renderPlan();
  }
  el.planSelect.addEventListener('change', () => {
    if (S.running) return;
    const p = S.plans.find(x => x.dir === el.planSelect.value);
    S.current = p ? { dir: p.dir, plan: p.plan, results: p.results } : null;
    renderPlan();
  });

  function windowStatus(i) {
    const rs = (S.current.results || []).filter(r => r.index === i);
    if (!rs.length) return { cls: 'pending', label: '' };
    if (rs.some(r => r.status === 'feil') && !rs.some(r => r.status === 'ok' || r.status === 'tom')) return { cls: 'err', label: rs.filter(r => r.status === 'feil').slice(-1)[0].error || 'feil' };
    if (rs.every(r => r.status === 'tom')) return { cls: 'empty', label: 'ingenting i vinduet' };
    const n = rs.filter(r => r.status === 'ok').length;
    return { cls: 'ok', label: n > 1 ? n + ' sikringer' : 'sikret' };
  }
  function doneCount() {
    if (!S.current) return 0;
    return S.current.plan.windows.filter((w, i) => ['ok', 'empty'].includes(windowStatus(i).cls)).length;
  }

  function renderPlan() {
    const c = S.current;
    el.form.hidden = !!c;
    el.planBtn.hidden = !!c;
    el.runBtn.hidden = !c;
    el.stopBtn.hidden = !c;
    el.planBox.hidden = !c;
    if (!c) { el.runBtn.disabled = true; el.stopBtn.disabled = true; updateForm(); return; }
    const p = c.plan, done = doneCount(), total = p.windows.length;
    el.planMeta.innerHTML = esc((PLAT[p.platform] || p.platform) + ' · ' + p.account.handle) + '<br>' +
      esc(fmtD(p.period.from) + ' – ' + fmtD(p.period.to) + ' · ' + total + ' nedslag à ' + p.method.windowDays + ' døgn') + '<br>' +
      '<span class="bv-muted">Plan laget ' + esc(p.createdAtLocal) + ' · ' + done + ' av ' + total + ' ferdig</span>';
    el.planList.innerHTML = p.windows.map((w, i) => {
      const st = windowStatus(i);
      const extra = p.platform === 'youtube' ? (w.videos.length ? w.videos.length + ' video' + (w.videos.length > 1 ? 'er' : '') : 'ingen videoer') : '';
      return '<li class="bv-plan__row is-' + st.cls + '" data-i="' + i + '"><span class="bv-plan__n">' + (i + 1) + '</span>' +
        '<span class="bv-plan__d">' + esc(w.from === w.lastDay ? fmtD(w.from) : fmtD(w.from) + ' – ' + fmtD(w.lastDay)) + (extra ? ' <span class="bv-muted">· ' + esc(extra) + '</span>' : '') + '</span>' +
        '<span class="bv-plan__s" title="' + esc(st.label) + '">' + ({ ok: '✓', empty: '–', err: '✗', pending: '', running: '…' }[st.cls] || '') + '</span></li>';
    }).join('');
    el.runBtn.disabled = S.running || done === total;
    el.runBtn.textContent = done === 0 ? 'Kjør plan' : (done === total ? 'Ferdig' : 'Fortsett (' + (total - done) + ' igjen)');
    el.stopBtn.disabled = !S.running;
  }

  el.planReveal.addEventListener('click', () => { if (S.current) api.revealInFinder(S.current.dir + '/plan.txt'); });
  $('planNewBtn').addEventListener('click', () => { if (S.running) return; S.current = null; el.planSelect.value = ''; renderPlan(); });

  el.planBtn.addEventListener('click', async () => {
    if (S.running) return;
    const caseName = els.caseInput.value.trim();
    if (!caseName) { setStatus('Skriv inn en sak først', 'err'); els.caseInput.focus(); return; }
    if (!el.account.value.trim()) { setStatus('Skriv inn kontoen', 'err'); el.account.focus(); return; }
    if (!countWindows()) { setStatus('Velg en gyldig periode', 'err'); return; }
    setBusy(true);
    setStatus('Lager plan …');
    try {
      const r = await api.bevisPlanCreate({
        root: state.root, caseName, account: el.account.value.trim(), platform: el.platform.value,
        from: el.from.value, to: el.to.value, mode: el.mode.value, n: +el.n.value, windowDays: +el.win.value,
        perWindow: +el.per.value, note: els.noteInput.value.trim(), pluginVersion: state.pluginVersion,
      });
      if (!r.ok) { setStatus('Kunne ikke lage plan: ' + r.error, 'err'); return; }
      const empty = r.plan.platform === 'youtube' ? r.plan.windows.filter(w => !w.videos.length).length : 0;
      setStatus('Planen er lagret (' + r.plan.windows.length + ' nedslag' + (empty ? ', ' + empty + ' uten videoer' : '') + '). Se gjennom og trykk «Kjør plan».', 'ok');
      await loadPlans(r.dir);
    } finally { setBusy(false); renderPlan(); }
  });

  el.stopBtn.addEventListener('click', () => { if (S.running) { S.stop = true; setStatus('Stopper etter dette nedslaget …'); } });

  // ------------------------------------------------------------
  //  Kjøring
  // ------------------------------------------------------------
  async function logResult(result) {
    await api.bevisPlanResult({ dir: S.current.dir, result });
    (S.current.results = S.current.results || []).push(Object.assign({ at: new Date().toISOString() }, result));
    renderPlan();
  }

  async function captureOne(url, sample, maxScroll) {
    if (window.bvRootReady && !window.bvRootReady()) return { status: 'feil', error: 'ingen arkivmappe', login: true };
    const open = await api.bevisOpen({ url, wait: true, settleMs: 3000 });
    if (!open.ok) return { status: 'feil', error: 'kunne ikke åpne siden' };
    if (/\/(login|i\/flow\/login|accounts\/login)/.test(open.finalUrl || '')) return { status: 'feil', error: 'krever innlogging', login: true };
    const r = await api.bevisCapture({
      root: state.root, caseName: S.current.plan.case, note: els.noteInput.value.trim(), url,
      pluginVersion: state.pluginVersion, options: options(), sample, maxScroll,
    });
    if (!r.ok) return { status: 'feil', error: r.error };
    return { status: 'ok', dir: r.dir, fingerprint: r.fingerprint, warnings: (r.warnings || []).length };
  }

  el.runBtn.addEventListener('click', async () => {
    if (S.running || !S.current) return;
    const p = S.current.plan;
    S.running = true; S.stop = false;
    setBusy(true); renderPlan();
    const total = p.windows.length;
    try {
      for (let i = 0; i < total; i++) {
        if (S.stop) break;
        if (['ok', 'empty'].includes(windowStatus(i).cls)) continue;
        const w = p.windows[i];
        const row = el.planList.querySelector('[data-i="' + i + '"]');
        if (row) { row.className = 'bv-plan__row is-running'; row.scrollIntoView({ block: 'nearest' }); }
        const base = { planId: p.id, index: i, total, from: w.from, lastDay: w.lastDay, until: w.until, platform: p.platform, account: p.account.handle };
        if (p.platform === 'x') {
          setStatus('Nedslag ' + (i + 1) + ' av ' + total + ': ' + fmtD(w.from) + ' …');
          const res = await captureOne(w.url, Object.assign({}, base, { url: w.url, query: decodeURIComponent((w.url.match(/q=([^&]+)/) || [, ''])[1]) }), 25);
          await logResult(Object.assign({ index: i }, res));
          if (res.login) { setStatus('X krever innlogging. Logg inn i sikringsvinduet og trykk «Fortsett».', 'err'); break; }
          if (i < total - 1 && !S.stop && window.bvPace) await window.bvPace(() => S.stop);
        } else if (p.platform === 'youtube') {
          if (!w.videos.length) { await logResult({ index: i, status: 'tom' }); continue; }
          for (const v of w.videos) {
            if (S.stop) break;
            setStatus('Nedslag ' + (i + 1) + ' av ' + total + ': ' + (v.title || v.id).slice(0, 60) + ' …');
            const res = await captureOne(v.url, Object.assign({}, base, { videoId: v.id, videoDateApprox: v.date, url: v.url }), 4);
            await logResult(Object.assign({ index: i, videoId: v.id }, res));
            if (!S.stop && window.bvPace) await window.bvPace(() => S.stop);
          }
        }
        await refresh();
      }
    } finally {
      S.running = false;
      setBusy(false);
      const done = doneCount();
      if (!/krever innlogging/.test(els.status.textContent)) {
        setStatus(S.stop ? 'Stoppet — ' + done + ' av ' + total + ' ferdig. «Fortsett» tar resten.' : (done === total ? 'Planen er gjennomført: ' + total + ' nedslag.' : done + ' av ' + total + ' ferdig — noen feilet, trykk «Fortsett» for å prøve dem igjen.'), done === total ? 'ok' : 'warn');
      }
      S.stop = false;
      renderPlan();
      await refresh();
    }
  });

  // ------------------------------------------------------------
  //  Lagring (kalles fra main.js)
  // ------------------------------------------------------------
  window.bvSampleState = () => ({
    mode: S.mode, platform: el.platform.value, account: el.account.value, from: el.from.value, to: el.to.value,
    smode: el.mode.value, n: el.n.value, win: el.win.value, per: el.per.value,
  });
  window.bvSampleApply = (s) => {
    if (s) {
      if (s.platform && el.platform.querySelector('option[value="' + s.platform + '"]:not([disabled])')) el.platform.value = s.platform;
      el.account.value = s.account || '';
      el.from.value = s.from || ''; el.to.value = s.to || '';
      if (s.smode) el.mode.value = s.smode;
      if (s.n) el.n.value = s.n;
      if (s.win) el.win.value = s.win;
      if (s.per) el.per.value = s.per;
    }
    if (!el.to.value) el.to.value = new Date().toISOString().slice(0, 10);
    updateForm();
    setMode(s && s.mode);
  };
  window.bvSampleRunning = () => S.running;
})();

style.css:
/* Bevissikring — basisoppsett kopiert fra skjermarkiv, egne regler nederst */

.plugin-page {
  flex: 1;
  display: grid;
  grid-template-columns: 313px 1fr;
  gap: 22px;
  overflow: hidden;
  padding: 4px;
}

.plugin-sidebar {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 0 4px 4px;
  min-height: 0;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,0.3) transparent;
}
.plugin-sidebar::-webkit-scrollbar { width: 8px; }
.plugin-sidebar::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,0.3);
  border-radius: 4px;
}
/* Kopier embed-knappen pinnes nede så den alltid er synlig */
#copyEmbedBtn {
  position: sticky;
  bottom: 0;
  z-index: 10;
  box-shadow: 0 -10px 14px -4px rgba(157,157,157,0.7);
}

.plugin-sidebar__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}
.plugin-sidebar__title {
  font-family: var(--font-bold);
  font-size: 22px;
  font-weight: bold;
  color: #212121;
  margin: 0;
  line-height: 1.05;
}

.plugin-sidebar__desc { display: none; }

.plugin-sidebar__spacer { /* deaktivert — tb-section tar all ledig plass */ }

.caption-section { display: flex; flex-direction: column; gap: 3px; }
.caption-input {
  background: var(--bg-input);
  border: 0;
  outline: 0;
  border-radius: 6px;
  padding: 6px 11px;
  font-weight: bold;
  font-size: 12px;
  color: var(--text-input);
  resize: vertical;
  line-height: 1.3;
  font-family: inherit;
}
.caption-input--single { height: 32px; padding: 0 11px; }
.caption-input::placeholder { color: #888; font-weight: normal; }

.plugin-sidebar__status {
  font-size: 13px;
  color: #fff;
  min-height: 18px;
  opacity: 0.85;
}

.url-section { display: flex; flex-direction: column; gap: 6px; }
.url-section--compact { gap: 6px; }
.url-section__label {
  font-family: var(--font-bold);
  font-size: 12px;
  font-weight: bold;
  color: #fff;
}
.url-section__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}
.link-btn {
  background: transparent;
  color: #fff;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 12px;
  cursor: pointer;
  text-decoration: underline;
  text-decoration-color: rgba(255,255,255,0.5);
  text-underline-offset: 3px;
}
.link-btn:hover { text-decoration-color: #fff; }

.url-row {
  background: var(--bg-input);
  border-radius: 6px;
  padding: 11px 14px;
  display: flex;
  align-items: center;
}
.url-row__input {
  display: block;
  flex: 1;
  background: var(--bg-input);
  border: 0;
  outline: 0;
  padding: 11px 14px;
  border-radius: 6px;
  font-family: var(--font-bold);
  font-size: 12px;
  line-height: 1.3;
  color: var(--text-input);
  font-weight: bold;
  min-width: 0;
  width: 100%;
  box-sizing: border-box;
  appearance: none;
  -webkit-appearance: none;
}
.url-row__input::placeholder { color: #888; font-weight: normal; }

/* Legacy klasse — peker nå til samme stil som btn-mini */
.btn-tiny {
  background: var(--faktisk-blue);
  color: #fff;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 12px;
  padding: 5px 9px;
  border-radius: 6px;
  white-space: nowrap;
  border: 0;
  cursor: pointer;
}
.btn-tiny:hover { background: var(--faktisk-blue-hover); }

.project-row { display: flex; gap: 4px; }
.project-row .project-select { flex: 1; }
.project-select {
  width: 100%;
  height: 32px;
  background: var(--bg-input);
  border: 0;
  border-radius: 6px;
  padding: 0 28px 0 11px;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 12px;
  color: var(--text-input);
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='12' height='8' viewBox='0 0 12 8'><path d='M1 1l5 5 5-5' stroke='%23313131' stroke-width='2' fill='none' stroke-linecap='round' stroke-linejoin='round'/></svg>");
  background-repeat: no-repeat;
  background-position: right 10px center;
}

.btn-primary:disabled { opacity: 0.4; cursor: not-allowed; }

/* Canvas — slider preview */
.plugin-canvas {
  display: flex;
  flex-direction: column;
  /* IKKE overflow:hidden — tekstbokser skal kunne stikke ut av kart-området */
  overflow: visible;
  min-width: 0;
  gap: 20px;
  padding: 8px 0;
}

/* «Før» / «Etter»-bokser over bildet */
.slider-labels {
  display: flex;
  justify-content: space-between;
  align-items: center;
  pointer-events: none;
  flex: 0 0 auto;
}
.slider-label {
  background: #0050FC;
  color: #fff;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: clamp(14px, 1.8cqw, 22px);
  padding: 0.3em 0.65em;
  border-radius: 5px;
  line-height: 1.25;
}

/* Sidebar: toggle + felt for Før/Etter-tekster */
.labels-section {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.check-row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: #fff;
  font-family: var(--font-bold);
  font-weight: bold;
  cursor: pointer;
  user-select: none;
}
.check-row input[type="checkbox"] {
  accent-color: var(--faktisk-blue);
  margin: 0;
  cursor: pointer;
}
.labels-inputs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
}
.labels-section.is-off .labels-inputs { display: none; }

/* Liten kompakt input — brukt på Før/Etter-tekst-felter (mindre enn URL-felt) */
.input-mini {
  background: var(--bg-input);
  border: 0;
  outline: 0;
  height: 32px;
  padding: 0 11px;
  border-radius: 6px;
  font-family: var(--font-bold);
  font-size: 12px;
  color: var(--text-input);
  font-weight: bold;
  width: 100%;
  box-sizing: border-box;
}
.input-mini::placeholder { color: #888; font-weight: normal; }

.slider-stage {
  position: relative;
  flex: 1;
  background: transparent;
  /* INGEN overflow:hidden her — slipper tekstbokser stikker ut.
     Klippingen skjer på .slider-clipper innenfor. */
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 0;
}

.slider-empty {
  padding: 40px;
  text-align: center;
}
.slider-empty p {
  max-width: 420px;
  font-size: 16px;
  color: #fff;
  margin: 0;
  line-height: 1.4;
}

.slider-preview {
  position: relative;
  width: 100%;
  height: 100%;
  user-select: none;
  container-type: inline-size;
}
/* Klipper for bildene + slider-handle + arrows/dots — tekstbokser ligger UTENFOR */
.slider-clipper {
  position: absolute;
  inset: 0;
  overflow: hidden;
  border-radius: 10px;
  background: var(--bg-letterbox);
}

.slider-img {
  position: absolute;
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  pointer-events: none;
}

.slider-clip {
  position: absolute;
  width: 100%;
  height: 100%;
  clip-path: inset(0 50% 0 0);
  transition: clip-path 0.05s linear;
  pointer-events: none;
}

.slider-handle {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: clamp(5px, 0.9cqw, 9px);
  background: #fff;
  transform: translateX(-50%);
  cursor: ew-resize;
  z-index: 3;
}

.slider-handle__line {
  position: absolute;
  inset: 0;
  background: #fff;
}

.slider-handle__knob {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: clamp(28px, 4.2cqw, 38px);
  height: clamp(20px, 3cqw, 28px);
  background: #fff;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 6px rgba(0,0,0,0.3);
}
.slider-handle__knob svg {
  width: 78%;
  height: 78%;
}

/* Tekstboks-seksjon i sidebar — Figma-stil med scroll-container */
.tb-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 0 0 auto;
}
.tb-section__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
/* Grå scroll-container som inneholder tekstboks-radene */
.tb-list {
  background: #929292;
  border-radius: 6px;
  padding: 10px 8px;
  max-height: 180px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 4px;
  scrollbar-width: thin;
  scrollbar-color: #6e6e6e #888;
}
.tb-list::-webkit-scrollbar { width: 8px; }
.tb-list::-webkit-scrollbar-track { background: #888; border-radius: 4px; }
.tb-list::-webkit-scrollbar-thumb { background: #6e6e6e; border-radius: 4px; }
.tb-list:empty::before {
  content: "Ingen tekstbokser ennå. Trykk «+ Legg til»";
  color: rgba(255,255,255,0.85);
  font-size: 12px;
  font-style: italic;
  padding: 4px 2px;
}

.tb-row {
  display: grid;
  grid-template-columns: 24px 1fr 24px 24px;
  gap: 4px;
  align-items: flex-start;
}
.tb-row__chip {
  height: 24px;
  border-radius: 6px;
  cursor: pointer;
  border: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: bold;
  font-family: var(--font-bold);
  color: #fff;
}
.tb-row__chip--light { background: #a2a2a2; }
.tb-row__chip--dark { background: var(--faktisk-blue); }

.tb-row__input {
  background: #D4D4D4;
  border: 0;
  outline: 0;
  border-radius: 6px;
  padding: 4px 9px;
  min-height: 24px;
  font-family: var(--font-bold);
  font-size: 12px;
  color: #212121;
  font-weight: bold;
  resize: vertical;
  line-height: 1.3;
  font-family: inherit;
}
.tb-row__input::placeholder { color: #666; font-weight: normal; }
input.tb-row__input { height: 24px; padding: 0 9px; }
textarea.tb-row__input { min-height: 36px; }

/* Peker-toggle (↗) og slett (×) — like små grå knapper */
.tb-row__btn {
  background: #a2a2a2;
  color: #fff;
  border: 0;
  width: 24px;
  height: 24px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 12px;
  font-weight: bold;
  font-family: var(--font-bold);
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.tb-row__btn:hover { background: #888; }
.tb-row__btn--active { background: #f18181; }   /* peker aktiv */
.tb-row__btn--del:hover { background: #c95c5c; }

/* Kompakt Figma-knapp — brukes overalt i sidebar */
.btn-mini {
  background: var(--faktisk-blue);
  color: #fff;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 12px;
  padding: 5px 9px;
  border-radius: 6px;
  border: 0;
  cursor: pointer;
  white-space: nowrap;
  line-height: 1.3;
}
.btn-mini:hover:not(:disabled) { background: var(--faktisk-blue-hover); }
.btn-mini:disabled { opacity: 0.4; cursor: not-allowed; }
.btn-mini--block { width: 100%; text-align: center; }
.btn-mini--light { background: #a2a2a2; }
.btn-mini--light:hover:not(:disabled) { background: #888; }

.tb-add-buttons {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

/* Tekstbokser PÅ preview (drag-bare) — matcher embed-størrelser */
.tb-overlay {
  position: absolute;
  padding: 0.45em 0.95em;
  border-radius: 5px;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: clamp(14px, 1.8cqw, 26px);
  line-height: 1.25;
  cursor: move;
  user-select: none;
  pointer-events: auto;
  white-space: nowrap;
  transform: translate(-50%, -50%);
  z-index: 4;
  box-shadow: 0 2px 6px rgba(0,0,0,0.3);
}
.tb-overlay--light {
  background: #D9D9D9;
  color: #212121;
  font-weight: normal;
  font-size: clamp(14px, 1.6cqw, 22px);
  white-space: normal;
  word-break: break-word;
  /* Bredden hentes fra --tb-w (settes inline per boks).
     Preview-vinduet er typisk bredt, så ingen mobile-overstyring er nødvendig her. */
  width: var(--tb-w, 28%);
}
.tb-overlay--dark { background: #0050fc; color: #fff; }
/* Resize-håndtak (lite blått punkt nedre-høyre) for light-bokser */
.tb-overlay__resize {
  position: absolute;
  right: -6px;
  bottom: -6px;
  width: 12px;
  height: 12px;
  background: #fff;
  border: 2px solid #0050fc;
  border-radius: 50%;
  cursor: ew-resize;
  z-index: 5;
}
.tb-overlay.is-selected { outline: 2px dashed #fff; outline-offset: 2px; }

/* Markeringer (frittstående sirkler) i preview */
.bm-marker {
  position: absolute;
  transform: translate(-50%, -50%);
  aspect-ratio: 1;
  cursor: move;
  z-index: 4;
  box-shadow: 0 2px 6px rgba(0,0,0,0.4);
}
.bm-marker--filled {
  background: var(--mark-color, #0050fc);
  border-radius: 50%;
}
.bm-marker--open {
  border: 4px solid var(--mark-color, #0050fc);
  border-radius: 50%;
  background: transparent;
}
.bm-marker__scale {
  position: absolute;
  right: -8px;
  bottom: -8px;
  width: 16px;
  height: 16px;
  background: #fff;
  border: 2px solid #0050fc;
  border-radius: 50%;
  cursor: nwse-resize;
  z-index: 5;
}

/* Marker-seksjon i sidebar — samme stil som tb-section */
.marker-section { display: flex; flex-direction: column; gap: 8px; flex: 0 0 auto; }

/* Peker-sirkel — bevarer proporsjon (HTML-div, ikke SVG) + puls-ring.
   Farge styres via variant-modifier (--dot-color custom prop). */
.tb-pointer-circle {
  position: absolute;
  width: 28px;
  height: 28px;
  transform: translate(-50%, -50%);
  cursor: move;
  z-index: 5;
  pointer-events: auto;
  --dot-color: #fff;
}
.tb-pointer-circle--dark { --dot-color: #0050fc; }
.tb-pointer-circle--light { --dot-color: #fff; }
/* Åpen ring: erstatt fyll med border + transparent inside */
.tb-pointer-circle--open .tb-pointer-dot-inner {
  background: transparent;
  border: 4px solid var(--dot-color);
  box-sizing: border-box;
}
.tb-pointer-circle--open .tb-pointer-pulse {
  background: transparent;
  border: 3px solid var(--dot-color);
  box-sizing: border-box;
}
/* Skalerings-håndtak på peker-sirkel (lite hvitt punkt nedre-høyre) */
.tb-pointer-scale {
  position: absolute;
  right: -6px;
  bottom: -6px;
  width: 12px;
  height: 12px;
  background: #fff;
  border: 2px solid #0050fc;
  border-radius: 50%;
  cursor: nwse-resize;
  z-index: 6;
}
.tb-pointer-dot-inner {
  position: absolute;
  inset: 0;
  background: var(--dot-color);
  border-radius: 50%;
  box-shadow: 0 1px 4px rgba(0,0,0,0.5);
  z-index: 2;
}
.tb-pointer-pulse {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: var(--dot-color);
  opacity: 0.55;
  animation: tb-pulse 1.8s ease-out infinite;
  pointer-events: none;
  z-index: 1;
}
@keyframes tb-pulse {
  0%   { transform: scale(1);   opacity: 0.55; }
  80%  { transform: scale(2.6); opacity: 0;    }
  100% { transform: scale(2.6); opacity: 0;    }
}

/* ============================================================
   Klippsetter-spesifikt
   ============================================================ */

.ks-video {
  max-width: 100%;
  max-height: 100%;
  border-radius: 8px;
  background: #000;
  box-shadow: 0 4px 18px rgba(0,0,0,0.35);
}

.ks-total {
  font-size: 11px;
  color: rgba(255,255,255,0.7);
}

.ks-clip {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  border-radius: 8px;
  background: rgba(255,255,255,0.07);
  margin-bottom: 5px;
}
.ks-clip--active { background: rgba(0,80,252,0.28); }
.ks-clip__num {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #0050FC;
  color: #fff;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.ks-clip__name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: left;
  border: 0;
  background: transparent;
  color: #fff;
  font-family: inherit;
  font-size: 12px;
  cursor: pointer;
  padding: 0;
}
.ks-clip__dur {
  flex-shrink: 0;
  font-size: 11px;
  color: rgba(255,255,255,0.7);
  font-variant-numeric: tabular-nums;
}
.ks-clip__dur--trim { color: #FFD166; }
.ks-clip__btns {
  flex-shrink: 0;
  display: inline-flex;
  gap: 2px;
}

.ks-trim {
  margin-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.ks-trim__row {
  display: flex;
  gap: 6px;
}
.ks-trim__info {
  font-size: 11px;
  color: rgba(255,255,255,0.75);
  font-variant-numeric: tabular-nums;
}

.ks-opts {
  margin-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.ks-check {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 12px;
  color: #fff;
  cursor: pointer;
  user-select: none;
}
.ks-check input { accent-color: #0050FC; }

.export-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 10px;
}
.export-progress {
  height: 6px;
  border-radius: 3px;
  background: rgba(255,255,255,0.15);
  overflow: hidden;
}
.export-progress__bar {
  height: 100%;
  width: 0;
  background: #0050FC;
  transition: width 0.3s;
}
.export-note {
  font-size: 11px;
  color: rgba(255,255,255,0.65);
  margin: 0;
  line-height: 1.4;
}

/* ============================================================
   Bevissikring — egne regler
   ============================================================ */
.bv-desc { font-size: 12.5px; line-height: 1.45; color: #fff; opacity: 0.85; margin: 0; }
.bv-block { display: flex; flex-direction: column; gap: 6px; }
.bv-block--foot { margin-top: 6px; padding-top: 10px; border-top: 1px solid rgba(255,255,255,0.25); }
.bv-row { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.bv-urlrow { display: flex; gap: 6px; align-items: stretch; }
.bv-urlrow .url-row__input { flex: 1; }
.bv-urlrow .btn-mini { flex-shrink: 0; padding-left: 14px; padding-right: 14px; }
.bv-hint { font-size: 11.5px; line-height: 1.4; color: #fff; opacity: 0.8; margin: 0; }
.bv-hint--warn { color: #FFE08A; opacity: 1; }
.bv-check { display: flex; align-items: center; gap: 6px; font-size: 12px; font-weight: bold; color: #fff; cursor: pointer; }
.bv-check input { accent-color: #0050FC; margin: 0; }
.bv-check--sub { padding-left: 20px; font-weight: normal; }
.bv-check input:disabled + span { opacity: 0.5; }
.bv-win { display: flex; align-items: center; gap: 7px; font-size: 12px; color: #fff; min-height: 18px; }
.bv-win__dot { width: 8px; height: 8px; border-radius: 50%; background: rgba(255,255,255,0.45); flex-shrink: 0; }
.bv-win.is-open .bv-win__dot { background: #3DDC84; box-shadow: 0 0 0 3px rgba(61,220,132,0.25); }
.bv-win__text { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: bold; }
.bv-actions { display: flex; flex-direction: column; gap: 6px; position: sticky; bottom: 0; z-index: 5; padding: 6px 0 2px; background: var(--bg-page); }
.bv-go { width: 100%; font-size: 15px; padding: 12px 14px; }
.bv-root { font-size: 11.5px; color: #fff; word-break: break-all; user-select: text; -webkit-user-select: text; opacity: 0.9; }
.bv-tools { font-size: 11.5px; color: #fff; opacity: 0.75; }
.bv-status--ok { color: #fff !important; font-weight: bold; }
.bv-status--warn { color: #FFE08A !important; }
.bv-status--err { color: #FFD0D0 !important; font-weight: bold; }

.bv-canvas { gap: 10px; overflow: hidden; min-height: 0; }
.bv-toolbar { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.bv-search { flex: 1 1 240px; min-width: 180px; height: 36px; border: 0; border-radius: 6px; padding: 0 12px; background: var(--bg-input); color: var(--text-input); font-weight: bold; font-size: 13px; outline: none; }
.bv-search:focus { box-shadow: 0 0 0 2px rgba(0,80,252,0.6); }
.bv-select { width: auto; min-width: 170px; height: 36px; }
.bv-count { font-size: 12px; color: #fff; opacity: 0.8; font-variant-numeric: tabular-nums; }
.bv-list-wrap { flex: 1; min-height: 0; overflow-y: auto; padding-right: 4px; position: relative; }
.bv-list { display: flex; flex-direction: column; gap: 10px; }

.bv-card { display: grid; grid-template-columns: 180px 1fr; gap: 14px; background: #2b2b2b; border-radius: 10px; padding: 12px; color: #fff; }
.bv-card.is-new { box-shadow: 0 0 0 2px var(--faktisk-blue); }
.bv-thumb { display: block; width: 180px; height: 135px; border-radius: 6px; overflow: hidden; background: #111; align-self: start; }
.bv-thumb img { width: 100%; height: 100%; object-fit: cover; object-position: top; display: block; }
.bv-thumb:hover { box-shadow: 0 0 0 2px var(--faktisk-blue); }
.bv-thumb__none { display: flex; height: 100%; align-items: center; justify-content: center; color: #888; font-size: 12px; }
.bv-body { min-width: 0; display: flex; flex-direction: column; gap: 5px; }
.bv-top { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; font-size: 11.5px; color: #bbb; }
.bv-top time { margin-left: auto; font-variant-numeric: tabular-nums; }
.bv-badge { background: var(--faktisk-blue); color: #fff; font-weight: bold; font-size: 11px; padding: 2px 7px; border-radius: 4px; }
.bv-badge--light { background: #555; }
.bv-case { font-weight: bold; color: #ddd; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 40%; }
.bv-title { margin: 0; font-family: var(--font-bold); font-size: 15px; line-height: 1.25; overflow: hidden; text-overflow: ellipsis; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.bv-url { text-align: left; color: #9EC2FF; font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 100%; }
.bv-url:hover { text-decoration: underline; }
.bv-note { margin: 0; font-size: 12.5px; line-height: 1.4; color: #eee; background: rgba(255,255,255,0.06); border-radius: 6px; padding: 5px 8px; white-space: pre-wrap; user-select: text; -webkit-user-select: text; }
.bv-meta { font-size: 11.5px; color: #bbb; }
.bv-inline { font-size: 11.5px; color: #9EC2FF; }
.bv-hash { font-size: 11px; color: #999; font-family: ui-monospace, Menlo, monospace; user-select: text; -webkit-user-select: text; }
.bv-warn { margin: 0; padding: 0 0 0 16px; font-size: 11.5px; line-height: 1.4; color: #FFE08A; }
.bv-verify { font-size: 12px; border-radius: 6px; padding: 6px 8px; background: rgba(255,255,255,0.08); }
.bv-verify--ok { background: rgba(61,220,132,0.15); color: #9FF0C4; }
.bv-verify--bad { background: rgba(217,83,79,0.22); color: #FFC4C2; font-weight: bold; }
.bv-muted { color: #bbb; font-weight: normal; }
.bv-cardactions { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 4px; }

@media (max-width: 1100px) {
  .bv-card { grid-template-columns: 120px 1fr; }
  .bv-thumb { width: 120px; height: 90px; }
}

/* Stikkprøver */
.bv-seg { display: flex; background: rgba(0,0,0,0.22); border-radius: 7px; padding: 2px; }
.bv-seg button { flex: 1; background: transparent; color: #fff; font-family: var(--font-bold); font-weight: bold; font-size: 12px; padding: 7px 10px; border-radius: 5px; }
.bv-seg button.is-on { background: var(--faktisk-blue); }
.bv-sample-only { display: none !important; }
body.bv-mode-sample .bv-sample-only { display: revert !important; }
body.bv-mode-sample .bv-sample-only[hidden] { display: none !important; }
body.bv-mode-sample .bv-single-only { display: none !important; }
body.bv-mode-sample .bv-block.bv-sample-only { display: flex !important; }
body.bv-mode-sample .bv-block.bv-sample-only[hidden] { display: none !important; }
.bv-yt-only { display: none !important; }
body.bv-plat-youtube .bv-yt-only { display: flex !important; }
.bv-plat { width: 112px; flex-shrink: 0; height: auto; }
.bv-dates { display: flex; gap: 8px; }
.bv-dates label { flex: 1; display: flex; flex-direction: column; gap: 3px; font-size: 11.5px; font-weight: bold; color: #fff; }
.bv-date, .bv-num { background: var(--bg-input); border: 0; border-radius: 6px; height: 32px; padding: 0 8px; font-family: inherit; font-weight: bold; font-size: 12px; color: var(--text-input); outline: none; min-width: 0; }
.bv-num { width: 58px; text-align: right; }
.bv-inline-row { display: flex; align-items: center; gap: 6px; font-size: 12px; color: #fff; font-weight: bold; }
.bv-inline-row .project-select { flex: 1; min-width: 0; }
.bv-plan__meta { line-height: 1.5; }
.bv-plan__meta .bv-muted { color: #fff; opacity: 0.75; }
.bv-plan { list-style: none; margin: 0; padding: 0; max-height: 260px; overflow-y: auto; display: flex; flex-direction: column; gap: 2px; }
.bv-plan__row { display: flex; align-items: center; gap: 8px; padding: 4px 8px; border-radius: 5px; background: rgba(255,255,255,0.12); font-size: 12px; color: #fff; }
.bv-plan__n { width: 22px; text-align: right; opacity: 0.7; font-variant-numeric: tabular-nums; }
.bv-plan__d { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bv-plan__s { width: 16px; text-align: center; font-weight: bold; }
.bv-plan__row.is-ok { background: rgba(61,220,132,0.22); }
.bv-plan__row.is-empty { opacity: 0.6; }
.bv-plan__row.is-err { background: rgba(217,83,79,0.35); }
.bv-plan__row.is-running { background: var(--faktisk-blue); }
.bv-badge--sample { background: #7A4DD8; }

/* Chrome-kobling */
.bv-code { font-family: ui-monospace, Menlo, monospace; font-size: 12px; font-weight: bold; background: rgba(0,0,0,0.22); color: #fff; padding: 3px 7px; border-radius: 5px; letter-spacing: 0.06em; user-select: text; -webkit-user-select: text; }
.bv-warnline { color: #FFE08A; }
.bv-badge--chrome { background: #1E9E5A; }

/* Profil */
.bv-profile-only { display: none !important; }
body.bv-mode-profile .bv-block.bv-profile-only { display: flex !important; }
body.bv-mode-profile .bv-block.bv-profile-only[hidden] { display: none !important; }
body.bv-mode-profile .bv-single-only { display: none !important; }
.bv-posts { max-height: 340px; }
.bv-post { cursor: default; }
.bv-post input { margin: 0; accent-color: #0050FC; flex-shrink: 0; }
.bv-post__date { width: 78px; flex-shrink: 0; font-variant-numeric: tabular-nums; opacity: 0.9; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.bv-post.is-old { opacity: 0.55; }
.bv-badge--profile { background: #1877F2; }
.bv-del { margin-left: auto; }
.bv-del:hover { background: #C0392B !important; color: #fff !important; }

/* Import og søk */
.bv-drop { border: 2px dashed rgba(255,255,255,.35); border-radius: 8px; padding: 14px; font-size: 13px; text-align: center; display: flex; flex-direction: column; gap: 8px; align-items: center; }
.bv-drop.is-over { border-color: #fff; background: rgba(255,255,255,.1); }
.bv-implist { list-style: none; margin: 4px 0; padding: 0; font-size: 12px; max-height: 140px; overflow: auto; }
.bv-implist li { display: flex; justify-content: space-between; gap: 8px; padding: 2px 0; }
.bv-implist li span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bv-idxbar { display: flex; gap: 10px; align-items: center; justify-content: flex-end; margin: -4px 0 8px; min-height: 24px; }
.bv-idxbar [hidden] { display: none !important; }
.bv-hits { list-style: none; margin: 8px 0 0; padding: 0; }
.bv-hit { all: unset; cursor: pointer; display: block; font-size: 12.5px; line-height: 1.4; padding: 4px 8px; margin-top: 3px; border-radius: 4px; background: rgba(255,255,255,.06); }
.bv-hit:hover { background: rgba(255,255,255,.12); }
.bv-hit__src { font-weight: bold; color: #9DB8FF; }
.bv-hit mark { background: #E8B400; color: #000; border-radius: 2px; padding: 0 1px; }

/* Statuslinja ligger langt nede i panelet — klistres nederst så den alltid synes */
#status:not(:empty) { position: sticky; bottom: 0; z-index: 5; background: #2b2b2b; padding: 8px 10px; border-radius: 6px; box-shadow: 0 -2px 10px rgba(0,0,0,.3); opacity: 1; }

/* Arkivmappe, kryptert arkiv og innstillinger */
.bv-setup[hidden], .bv-vaultform[hidden], .bv-vault[hidden] { display: none !important; }
.bv-setup { background: rgba(232, 180, 0, .14); border: 2px solid #E8B400; border-radius: 8px; padding: 12px; }
.bv-vaultform { background: rgba(255, 255, 255, .07); border-radius: 8px; padding: 12px; }
.bv-vaultform input + input { margin-top: 6px; }
.bv-needroot { opacity: .55; }
.bv-vault { margin-top: 6px; }
.bv-vault .url-row__input { flex: 1; min-width: 0; }
.bv-field { display: flex; flex-direction: column; gap: 4px; font-size: 13px; margin: 6px 0; }
.bv-routine { font-size: 13px; margin-top: 6px; }
.bv-routine summary { cursor: pointer; font-weight: bold; }
.bv-routine ul { margin: 6px 0; padding-left: 18px; }
.bv-routine li { margin: 3px 0; }
.bv-stamped { color: #5CD08A; }
.bv-badge--follow { background: #C0392B; }
.bv-watch { font-size: 12px; margin-top: 6px; padding: 4px 8px; border-radius: 4px; background: rgba(30, 158, 90, .2); }
.bv-watch--warn { background: rgba(232, 180, 0, .22); }
.bv-watch--bad { background: rgba(192, 57, 43, .32); }
